import json
import os

import pytest
import requests
from playwright.sync_api import Page, expect

TIMEOUT = 5


@pytest.fixture(scope="session")
def api(base_url):
    return f"{base_url}/api"


@pytest.fixture(scope="session")
def token(api):
    credentials = {"email": os.environ["QA_EMAIL"], "password": os.environ["QA_PASSWORD"]}
    response = requests.post(f"{api}/auth/login", json=credentials, timeout=TIMEOUT)
    response.raise_for_status()
    return response.json()["token"]


@pytest.fixture
def order(api, token):
    headers = {"Authorization": f"Bearer {token}"}
    created = requests.post(f"{api}/orders", json={"productId": 1, "quantity": 1}, headers=headers, timeout=TIMEOUT).json()
    yield created
    requests.delete(f"{api}/orders/{created['id']}", headers=headers, timeout=TIMEOUT)


def test_signed_in_user_sees_their_new_order(page: Page, token, order):
    page.add_init_script(f"localStorage.setItem('gadgetly:token', {json.dumps(token)})")
    page.goto("/playground/account")

    expect(page.get_by_role("heading", name="My orders")).to_be_visible()
    expect(page.get_by_test_id(f"order-{order['id']}")).to_be_visible()


def test_deleting_an_order_returns_204(api, token, order):
    headers = {"Authorization": f"Bearer {token}"}
    response = requests.delete(f"{api}/orders/{order['id']}", headers=headers, timeout=TIMEOUT)

    assert response.status_code == 204, response.text
